using namespace DungeonStoneBat;
int Checks=0,Failures=0;
void Check(bool Pass,const char* Name) { ++Checks;if(!Pass)++Failures;std::cout<<(Pass?"PASS ":"FAIL ")<<Name<<'\n'; }
bool Near(double A,double B) { return std::abs(A-B)<1.e-8; }
int Count(const FResult& R,EEventKind Kind) { int N=0;for(const auto& E:R.Events)if(E.Kind==Kind)++N;return N; }
FWorldInput World(double X=100,double Y=0) {
 FWorldInput W;W.HasTarget=true;W.Target={X,Y,0};
 W.LegalLowPoint=[](const FLowPointRequest& Q){return Q.Candidate.Z==20;};
 W.NearestLegalLowPoint=[](FPoint P){FNearestLowResult R;R.Found=true;R.Point={P.X,P.Y,20};return R;};
 W.Sweep=[](const FSweepRequest&){return FSweepResult{};};
 W.SelectDueAttack=[](bool Peck,bool Wing){return Peck?EAttack::Peck:Wing?EAttack::Wing:EAttack::None;};return W;
}
void Awake(FBatKernel& K,FWorldInput W) { K.StepTo(0,W);K.StepTo(.8,W); }
void Start(FBatKernel& K,EAttack A,FWorldInput W) { Awake(K,W);K.TryStartAttack(A,W); }
